import { describe, it, expect, jest, beforeEach, afterEach } from '@jest/globals';

describe('LLMService', () => {

  beforeEach(() => {
    jest.clearAllMocks();
    // Reset modules to ensure fresh imports
    jest.resetModules();
  });

  describe('generateContent', () => {
    describe('when OpenAI API key is not configured', () => {
      it('should return placeholder content and log warning', async () => {
        // Ensure no API key is set
        delete process.env.OPENAI_API_KEY;
        
        // Import after setting env
        const { generateContent } = await import('../../src/services/llmService');
        const result = await generateContent('Test prompt');

        expect(result).toBe(
          'AI content generation is not available. Please configure OPENAI_API_KEY environment variable.',
        );
      });
    });

    describe('when OpenAI API key is configured', () => {
      beforeEach(() => {
        process.env.OPENAI_API_KEY = 'test-api-key';
      });

      afterEach(() => {
        delete process.env.OPENAI_API_KEY;
      });

      it('should generate content with user prompt only', async () => {
        const { generateContent } = await import('../../src/services/llmService');
        const result = await generateContent('Test prompt');

        // The mock returns 'Mock generated content' by default
        expect(result).toBe('Mock generated content');
      });

      it('should generate content with system message', async () => {
        const { generateContent } = await import('../../src/services/llmService');
        const result = await generateContent('User prompt', 'System message');

        // The mock returns 'Mock generated content' by default
        expect(result).toBe('Mock generated content');
      });

      it('should log token usage when available', async () => {
        const { generateContent } = await import('../../src/services/llmService');
        const result = await generateContent('Prompt');

        // Just verify the function completes successfully
        expect(result).toBe('Mock generated content');
      });

      it('should handle missing content gracefully', async () => {
        // We need to mock OpenAI to return null content
        const MockOpenAI = (await import('openai')).default as any;
        MockOpenAI.mockCreate.mockResolvedValueOnce({
          choices: [
            {
              message: {
                content: null,
              },
            },
          ],
        });

        const { generateContent } = await import('../../src/services/llmService');
        const result = await generateContent('Prompt');

        expect(result).toBe('No content generated');
      });

      it('should handle API errors gracefully', async () => {
        const MockOpenAI = (await import('openai')).default as any;
        const error = new Error('API rate limit exceeded');
        MockOpenAI.mockCreate.mockRejectedValueOnce(error);

        const { generateContent } = await import('../../src/services/llmService');
        const result = await generateContent('Prompt');

        expect(result).toBe('Failed to generate content. Please try again later.');
      });

      it('should handle network timeouts', async () => {
        const MockOpenAI = (await import('openai')).default as any;
        const error = new Error('Request timeout');
        error.name = 'TimeoutError';
        MockOpenAI.mockCreate.mockRejectedValueOnce(error);

        const { generateContent } = await import('../../src/services/llmService');
        const result = await generateContent('Prompt');

        expect(result).toBe('Failed to generate content. Please try again later.');
      });

      it('should handle invalid API responses', async () => {
        const MockOpenAI = (await import('openai')).default as any;
        MockOpenAI.mockCreate.mockResolvedValueOnce({});

        const { generateContent } = await import('../../src/services/llmService');
        const result = await generateContent('Prompt');

        expect(result).toBe('No content generated');
      });
    });
  });

  describe('generateBilingualContent', () => {
    describe('when OpenAI API key is not configured', () => {
      it('should return placeholder content in both languages', async () => {
        delete process.env.OPENAI_API_KEY;
        
        const { generateBilingualContent } = await import('../../src/services/llmService');
        const result = await generateBilingualContent('Test prompt');

        const expectedContent =
          'AI content generation is not available. Please configure OPENAI_API_KEY environment variable.';

        expect(result).toEqual({
          french: expectedContent,
          english: expectedContent,
        });
      });
    });

    describe('when OpenAI API key is configured', () => {
      beforeEach(() => {
        process.env.OPENAI_API_KEY = 'test-api-key';
      });

      afterEach(() => {
        delete process.env.OPENAI_API_KEY;
      });

      it('should generate and parse bilingual content correctly', async () => {
        const MockOpenAI = (await import('openai')).default as any;
        MockOpenAI.mockCreate.mockResolvedValueOnce({
          choices: [
            {
              message: {
                content: `FRENCH:
Contenu en français

ENGLISH:
Content in English`,
              },
            },
          ],
          usage: {
            total_tokens: 150,
          },
        });

        const { generateBilingualContent } = await import('../../src/services/llmService');
        const result = await generateBilingualContent('Generate content');

        expect(result).toEqual({
          french: 'Contenu en français',
          english: 'Content in English',
        });
      });

      it('should handle case-insensitive language markers', async () => {
        const MockOpenAI = (await import('openai')).default as any;
        MockOpenAI.mockCreate.mockResolvedValueOnce({
          choices: [
            {
              message: {
                content: `french:
Texte français

english:
English text`,
              },
            },
          ],
        });

        const { generateBilingualContent } = await import('../../src/services/llmService');
        const result = await generateBilingualContent('Generate content');

        expect(result).toEqual({
          french: 'Texte français',
          english: 'English text',
        });
      });

      it('should handle missing language sections', async () => {
        const MockOpenAI = (await import('openai')).default as any;
        MockOpenAI.mockCreate.mockResolvedValueOnce({
          choices: [
            {
              message: {
                content: 'Some content without proper formatting',
              },
            },
          ],
        });

        const { generateBilingualContent } = await import('../../src/services/llmService');
        const result = await generateBilingualContent('Generate content');

        // When parsing fails, it returns the full content for both languages
        expect(result).toEqual({
          french: 'Some content without proper formatting',
          english: 'Some content without proper formatting',
        });
      });

      it('should handle only French section present', async () => {
        const MockOpenAI = (await import('openai')).default as any;
        MockOpenAI.mockCreate.mockResolvedValueOnce({
          choices: [
            {
              message: {
                content: `FRENCH:
Seulement en français`,
              },
            },
          ],
        });

        const { generateBilingualContent } = await import('../../src/services/llmService');
        const result = await generateBilingualContent('Generate content');

        // When English section is missing, it gets the full content
        expect(result).toEqual({
          french: 'Seulement en français',
          english: `FRENCH:
Seulement en français`,
        });
      });

      it('should handle API errors gracefully', async () => {
        const MockOpenAI = (await import('openai')).default as any;
        const error = new Error('API error');
        MockOpenAI.mockCreate.mockRejectedValueOnce(error);

        const { generateBilingualContent } = await import('../../src/services/llmService');
        const result = await generateBilingualContent('Generate content');

        // It uses generateContent internally, which returns this error message
        expect(result).toEqual({
          french: 'Failed to generate content. Please try again later.',
          english: 'Failed to generate content. Please try again later.',
        });
      });
    });
  });

  describe('Token limit handling', () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = 'test-api-key';
    });

    afterEach(() => {
      delete process.env.OPENAI_API_KEY;
    });

    it('should respect max_tokens parameter', async () => {
      const { generateContent } = await import('../../src/services/llmService');
      const result = await generateContent('Generate content');

      // Just verify it works with the default mock
      expect(result).toBe('Mock generated content');
    });

    it('should handle token limit exceeded errors', async () => {
      const MockOpenAI = (await import('openai')).default as any;
      const error = new Error('Rate limit exceeded');
      MockOpenAI.mockCreate.mockRejectedValueOnce(error);

      const { generateContent } = await import('../../src/services/llmService');
      const result = await generateContent('Generate content');

      expect(result).toBe('Failed to generate content. Please try again later.');
    });
  });

  describe('Prompt validation', () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = 'test-api-key';
    });

    afterEach(() => {
      delete process.env.OPENAI_API_KEY;
    });

    it('should handle empty prompts', async () => {
      const { generateContent } = await import('../../src/services/llmService');
      const result = await generateContent('');

      // Should still work, even with empty prompt
      expect(result).toBe('Mock generated content');
    });

    it('should handle very long prompts', async () => {
      const { generateContent } = await import('../../src/services/llmService');
      const longPrompt = 'a'.repeat(10000);
      const result = await generateContent(longPrompt);

      expect(result).toBe('Mock generated content');
    });

    it('should handle special characters in prompts', async () => {
      const { generateContent } = await import('../../src/services/llmService');
      const specialPrompt = 'Test with special chars: <script>alert("xss")</script> & \' " \\n \\t';
      const result = await generateContent(specialPrompt);

      expect(result).toBe('Mock generated content');
    });
  });
});